var p=UnityEngine.Object.FindFirstObjectByType<CurtainCall.ItemArt.ItemGameplayPlayground>();
var mover=p.Player.GetComponent<CurtainCall.Player.PlayerMover>();var actor=p.Player.GetComponent<CurtainCall.Player.HumanoidPlayerPresentation>();var carry=CurtainCall.WaitingRoom.PropCarry.Instance;var state=CurtainCall.WaitingRoom.ExplorationState.Instance;
