var original=UnityEngine.InputSystem.InputSystem.settings;var oldFlags=original.hideFlags;original.hideFlags=UnityEngine.HideFlags.DontSave;var working=UnityEngine.Object.Instantiate(original);working.hideFlags=UnityEngine.HideFlags.DontSave;UnityEngine.InputSystem.InputSystem.settings=working;working.backgroundBehavior=UnityEngine.InputSystem.InputSettings.BackgroundBehavior.IgnoreFocus;working.editorInputBehaviorInPlayMode=UnityEngine.InputSystem.InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
var previous=UnityEngine.InputSystem.Keyboard.current;var keyboard=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>("KeyInventoryReview");keyboard.MakeCurrent();bool background=UnityEngine.Application.runInBackground;UnityEngine.Application.runInBackground=true;
var records=new System.Collections.Generic.List<object>();var failures=new System.Collections.Generic.List<string>();var steps=new System.Collections.Generic.List<System.Action>();int step=0,keyUid=0,lastFrame=-1;UnityEngine.Vector3 droppedAt=default;double next=UnityEditor.EditorApplication.timeSinceStartup+.6;
System.Action<string,bool> check=(name,pass)=>{records.Add(new{name,pass,frame=UnityEngine.Time.frameCount,message=state.LastMessage,carryMessage=carry.LastMessage});if(!pass)failures.Add(name);};
System.Action<UnityEngine.InputSystem.Key> down=k=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState(k));
System.Action up=()=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState());
System.Action tap=()=>{steps.Add(()=>down(UnityEngine.InputSystem.Key.F));steps.Add(up);steps.Add(()=>{});};
System.Action<UnityEngine.Vector3> move=v=>mover.SetStartPose(v,UnityEngine.Quaternion.identity);
steps.Add(()=>{check("two initial slots",carry.Held(0).Count==2);move(p.KeyPickup.position+UnityEngine.Vector3.back*.8f);});tap();
steps.Add(()=>{check("full inventory leaves world key",!pickup.Opened&&carry.Held(0).Count==2&&!carry.Held(0).Any(x=>x.ItemId=="route-key"));move(new UnityEngine.Vector3(-8,.05f,-8));p.Give("stake-puller");carry.RequestDrop();});
steps.Add(()=>move(p.KeyPickup.position+UnityEngine.Vector3.back*.8f));tap();
steps.Add(()=>{var key=carry.Held(0).FirstOrDefault(x=>x.ItemId=="route-key");keyUid=key.Uid;check("pickup enters slot",keyUid!=0&&pickup.Opened&&carry.Held(0).Count==2);check("key tool and icon",CurtainCall.ItemArt.ItemVisualAssets.IsTool(key.ItemId)&&CurtainCall.ItemArt.ItemVisualAssets.Icon(key.ItemId)!=null);p.Give("route-key");});
