steps.Add(()=>move(p.KeyDoor.position+UnityEngine.Vector3.back*.9f));tap();
steps.Add(()=>{check("stowed key cannot open door",carry.Selected(0).Uid==0&&!door.Opened);p.Give("route-key");move(new UnityEngine.Vector3(-6,.05f,-6));carry.RequestDrop();});
