steps.Add(()=>{check("acquisition history cannot unlock without key",pickup.Opened&&!door.Opened);p.Give(CurtainCall.WaitingRoom.StructureAExitRoute.Key2);});tap();
steps.Add(()=>{check("wrong key cannot unlock",!door.Opened);check("key variant icon and held visual",CurtainCall.ItemArt.ItemVisualAssets.Icon(CurtainCall.WaitingRoom.StructureAExitRoute.Key2)!=null&&actor.HeldItemVisual!=null);move(new UnityEngine.Vector3(8,.05f,-8));carry.RequestDrop();});
steps.Add(()=>move(droppedAt+UnityEngine.Vector3.back*.4f));tap();
steps.Add(()=>{check("floor pickup restores same key",carry.Held(0).Any(x=>x.Uid==keyUid)&&!carry.Floor.Any(x=>x.Item.Uid==keyUid));p.Give("route-key");move(p.KeyDoor.position+UnityEngine.Vector3.back*.9f);});tap();
steps.Add(()=>{check("matching selected key unlocks",door.Opened);check("key persists after use",carry.Held(0).Any(x=>x.Uid==keyUid));check("key use animation",actor.ItemMotion=="ItemManipulate"&&actor.HeldItemVisual!=null);var shop=CurtainCall.WaitingRoom.WaitingRoomShop.Instance;if(shop==null)shop=new UnityEngine.GameObject("Key purchase validation").AddComponent<CurtainCall.WaitingRoom.WaitingRoomShop>();check("keys excluded from shop",!shop.Catalog.Any(x=>CurtainCall.WaitingRoom.ExplorationKeys.IsKey(x.Id)));check("all key variants have tool entries",CurtainCall.WaitingRoom.ExplorationKeys.Targets.All(x=>CurtainCall.WaitingRoom.ItemCatalog.Get(CurtainCall.WaitingRoom.ExplorationKeys.ItemId(x)) is {} e&&e.kind==CurtainCall.WaitingRoom.ItemKind.Tool&&e.price==0));});
steps.Add(()=>{p.Give("route-key");check("test button puts key in slot",carry.Held(0).Count(x=>x.ItemId=="route-key")==1&&carry.Selected(0).Uid==keyUid);});
UnityEditor.EditorApplication.CallbackFunction tick=null;
System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;System.IO.File.WriteAllText("Tasks/Active/Task-20261101-088-item-art-interaction/Art/key-inventory-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{records,failures},Newtonsoft.Json.Formatting.Indented));UnityEngine.InputSystem.InputSystem.RemoveDevice(keyboard);UnityEngine.InputSystem.InputSystem.settings=original;original.hideFlags=oldFlags;UnityEngine.Object.DestroyImmediate(working);previous?.MakeCurrent();UnityEngine.Application.runInBackground=background;};
tick=()=>{if(!UnityEditor.EditorApplication.isPlaying){failures.Add("Play stopped");finish();return;}if(UnityEngine.Time.frameCount==lastFrame||UnityEditor.EditorApplication.timeSinceStartup<next)return;lastFrame=UnityEngine.Time.frameCount;try{if(step==steps.Count){finish();return;}steps[step++]();next=UnityEditor.EditorApplication.timeSinceStartup+.24;}catch(System.Exception e){failures.Add(e.ToString());finish();}};
UnityEditor.EditorApplication.update+=tick;return "Actual F and slot input validation started: capacity, pickup, stow, drop, wrong key, repickup, use, shop exclusion.";
